{
  "hypotheses": [
    {
      "team": "home",
      "reasons": [
        {
          "text": "Son Heung-min is level with Cha Bum-kun on 58 international goals, so a single goal in this friendly would give him the record outright and keep Korea pushing forward for the full match.",
          "var_ids": ["R13"]
        },
        {
          "text": "Kim Min-jae sat out team training for a second straight day and is unlikely to start, which points toward a more open, goals-up match state for the home side.",
          "var_ids": ["R1", "R6", "R8"]
        },
        {
          "text": "Korea's all-time record in this series is 11 wins, four draws and one loss, and the fixture is being used to assess a regional rival before the Asian Cup.",
          "var_ids": ["R12", "R14"]
        }
      ],
      "breaks": [
        {
          "text": "Kim Min-jae skipped on-field work and trained separately indoors for two consecutive days, so the defensive linchpin may be missing and the back line reshuffled.",
          "var_ids": ["R2", "R8", "R1"]
        },
        {
          "text": "The fatigue management around Kim Min-jae leaves Korea without its usual anchor, and Korea has scored 0.25 goals per game over its last five once the 3-0 outlier is removed.",
          "var_ids": ["R3", "R7"]
        },
        {
          "text": "Kim Min-jae's own remarks criticized insufficient pressing, pointing to defensive-shape problems that a possible absence would make worse.",
          "var_ids": ["R5", "R4"]
        }
      ]
    },
    {
      "team": "away",
      "reasons": [
        {
          "text": "Kim Min-jae is not in normal condition and is unlikely to start, so Uzbekistan's attackers meet a Korea back line that may be missing its defensive linchpin.",
          "var_ids": ["R4", "R6"]
        },
        {
          "text": "The missing defender tilts the match toward more goals, and Uzbekistan has scored in three consecutive matches, including 4-1 and 3-1 home wins.",
          "var_ids": ["R1", "R8"]
        },
        {
          "text": "The friendly offers a chance to assess a regional rival ahead of next year's Asian Cup, giving Uzbekistan's staff reason to field a full-strength side.",
          "var_ids": ["R14"]
        }
      ],
      "breaks": [
        {
          "text": "Kim Min-jae's problem is described as fatigue from recent matches rather than a serious injury, so he could still feature and steady the Korea back line.",
          "var_ids": ["R7", "R3"]
        },
        {
          "text": "Uzbekistan's all-time record in this series is one win, four draws and 11 defeats.",
          "var_ids": ["R12"]
        },
        {
          "text": "Uzbekistan travelled poorly in its most recent away matches, conceding three to DR Congo and five to Portugal.",
          "var_ids": ["R9", "R10"]
        }
      ]
    }
  ],
  "scenarios": [
    {
      "id": "s1_대량득점형",
      "outcomes": [[3, 1], [4, 2]],
      "driver_vars": ["R13", "R1", "R6"],
      "mechanism": "Kim Min-jae's likely absence removes Korea's deepest defensive anchor and pushes the game into an open, chance-heavy state, while Son Heung-min's chase of the outright international goals record keeps Korea attacking for a further goal rather than closing the match down."
    },
    {
      "id": "s2_우세팀_실점_동반형",
      "outcomes": [[2, 1], [3, 1]],
      "driver_vars": ["R4", "R8", "R1"],
      "mechanism": "Korea's attacking depth decides the match, but with the back line reshuffled around a doubtful linchpin and the match state pushed toward goals, Uzbekistan's scorers — who have found the net in three straight — pull one back."
    },
    {
      "id": "s3_핸디_대응형",
      "outcomes": [[1, 0], [2, 1]],
      "driver_vars": ["R7", "R13"],
      "mechanism": "Kim Min-jae's issue is fatigue rather than a serious injury, so Korea can still field a compact, recovery-managed back line and win narrowly, with a single Son Heung-min goal deciding it."
    },
    {
      "id": "s4_회귀_반전형",
      "outcomes": [[1, 2], [0, 2]],
      "driver_vars": ["R1", "R4", "R5", "R6"],
      "mechanism": "Korea's defensive linchpin is unlikely to start and the side's own internal criticism of insufficient pressing leaves space between the lines, giving Uzbekistan's front line the room to turn the match and take it."
    },
    {
      "id": "s5_저득점_무승부",
      "outcomes": [[1, 1], [0, 0]],
      "driver_vars": ["R3", "R7"],
      "mechanism": "Korea manages Kim Min-jae through separate indoor recovery work rather than risking him, and Uzbekistan arrives after a full rest window, so neither side forces the tempo in a friendly and the match settles into a low-scoring stalemate."
    }
  ]
}
